"""Builds a boarding manifest from the flight's standby waitlist."""

from datetime import datetime, timedelta, timezone

from standby_priority import Passenger, compute_priority_score, rank_by_priority

STANDBY_CUTOFF_MINUTES = 30


def minutes_to_departure(departure_time: datetime, now: datetime) -> float:
    return (departure_time - now).total_seconds() / 60


def is_still_eligible(departure_time: datetime, now: datetime) -> bool:
    return minutes_to_departure(departure_time, now) >= STANDBY_CUTOFF_MINUTES


def compute_fare_refund(original_fare: float, assigned_fare: float) -> float:
    """Amount owed back when a passenger clears into a lower fare class."""
    return max(0.0, original_fare - assigned_fare)


def build_boarding_manifest(passengers, available_seats, departure_time, now=None):
    now = now or datetime.now(timezone.utc)

    eligible = [p for p in passengers if is_still_eligible(departure_time, now)]

    scored = [(p, compute_priority_score(p, now)) for p in eligible]
    ranked = rank_by_priority(scored)

    manifest = []
    seats_left = available_seats
    for passenger, score in ranked:
        if seats_left <= 0:
            break
        manifest.append({
            "record_locator": passenger.record_locator,
            "score": round(score, 1),
        })
        seats_left -= 1

    return manifest


def _demo():
    now = datetime.now(timezone.utc)
    departure = now + timedelta(hours=2)
    passengers = [
        Passenger("AA111", "economy", "gold", now - timedelta(minutes=90)),
        Passenger("AA222", "economy", None, now - timedelta(minutes=30), prior_denied_boardings=2),
        Passenger("AA333", "business", "silver", now - timedelta(minutes=10), involuntary_misconnect=True),
    ]
    manifest = build_boarding_manifest(passengers, available_seats=2, departure_time=departure, now=now)
    for entry in manifest:
        print(entry["record_locator"], entry["score"])


if __name__ == "__main__":
    _demo()
